 e.append(dict(evidence_id=eid,school_id=sid,source_url=u[n],page_title=title(n),accessed_date=D,quoted_text=quote,evidence_type='School webpage',interpretation_note=note))
 if cat:c.append(dict(code_id=f'ac_b21_{sid}_{sum(x["school_id"]==sid for x in c)+1:02}',school_id=sid,category=cat,subcategory=sub,coding_level='Explicit',confidence='High',evidence_id=eid,coder_note='Assistant contextual review, codebook v1, 2026-10-30. '+note+' Public self-description, not independently verified practice.',review_status='Reviewed'))
