c.append(dict(code_id='ac_b21_36185466_02',school_id='36185466',category='Outdoor, nature, or place-based learning',subcategory='Outdoor practical learning; I Ur och Skur',coding_level='Explicit',confidence='High',evidence_id=e[-1]['evidence_id'],coder_note='Assistant contextual review, codebook v1, 2026-10-30. Unit body explicitly places practical learning outdoors; not inferred solely from provider brand. Public self-description, not verified practice.',review_status='Reviewed'))
add('36232577','bromma','Vi tror att våra extra fokusområden på språklig utveckling, matematik och rörelse bidrar till både skolglädje och ett livslångt lärande.','Explicit combined school priorities. Movement corroborated by separate school section of Puls för lärande; preschool and F-class outdoor descriptions not transferred. Language development alone is not international/intercultural profile.','Other stated profile','Mathematics, language development and movement')
